        min_password_len: *min_password_len,
        max_password_len: *max_password_len,
        file_number: *file_number,
        password_dictionary: password_dictionary.cloned(),
        starting_password: starting_password.cloned(),
        mask: mask.cloned(),
        custom_charsets,
    })
