                    }
                    // check if we should stop
                    if stop_signal.load(Ordering::Relaxed) {
                        if first_worker {
                            let password_display = String::from_utf8_lossy(&password_bytes);
                            progress_bar
                                .println(format!("Last password processed:{password_display}"));
                        }
                        break;
                    }
                    processed_delta = 0;
                }
            }
        })
        .unwrap()
}

